//! INTLCLDR (LEDGER SR137): CLDR 46 as data — R83, no ICU. `tables.rs` and `collation.rs` are generated by
//! `tools/gen_cldr.py` (encoding documented there); this module reads them.
//!
//! A data locale is a `Loc` whose `blob` holds one string per slot (U+0001-terminated) and whose `idx` holds the
//! byte offset of every 16th slot: reading a slot touches at most 16 short strings, nothing is decoded up front.
//! A slot that is empty inherits from the CLDR parent locale; U+0002 marks an explicit absence.

pub mod collation;
pub mod tables;

use alloc::string::String;
use alloc::vec::Vec;
pub use tables::slot;
use tables::*;

/// The plural categories in CLDR order (the slot order of every per-category family).
pub const CATS: [&str; 6] = ["zero", "one", "two", "few", "many", "other"];

pub fn cat_index(c: &str) -> usize {
    CATS.iter().position(|x| *x == c).unwrap_or(5)
}

/// A data locale (index into `tables::LOCS`).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct L(pub u8);

fn raw(l: usize, k: usize) -> &'static str {
    let loc = &LOCS[l];
    let b = loc.blob.as_bytes();
    let mut i = loc.idx[k >> 4] as usize;
    for _ in 0..(k & 15) {
        while b[i] != 1 {
            i += 1;
        }
        i += 1;
    }
    let mut j = i;
    while b[j] != 1 {
        j += 1;
    }
    &loc.blob[i..j]
}

impl L {
    /// The root English data (`en`), the fallback of every lookup.
    pub const EN: L = L(0);

    /// Slot `k` resolved through the parent chain.
    pub fn get(self, k: usize) -> Option<&'static str> {
        let mut l = self.0 as usize;
        loop {
            let v = raw(l, k);
            if v == "\u{2}" {
                return None;
            }
            if !v.is_empty() {
                return Some(v);
            }
            let p = LOCS[l].parent;
            if p == 255 {
                return None;
            }
            l = p as usize;
        }
    }
    /// Slot `k`, or "" when absent.
    pub fn s(self, k: usize) -> &'static str {
        self.get(k).unwrap_or("")
    }
    /// Field `field` of `key` in a keyed family (`keys`, base slot, fields per key).
    pub fn keyed(self, keys: &[&str], base: usize, fields: usize, key: &str, field: usize) -> Option<&'static str> {
        let i = keys.binary_search(&key).ok()?;
        self.get(base + i * fields + field)
    }
    pub fn tag(self) -> &'static str {
        LOCS[self.0 as usize].tag
    }
    pub fn lang(self) -> &'static str {
        LOCS[self.0 as usize].lang
    }
    /// The CLDR parent (None for a root-level locale).
    pub fn parent(self) -> Option<L> {
        let p = LOCS[self.0 as usize].parent;
        if p == 255 { None } else { Some(L(p)) }
    }

    // ---- numbers
    pub fn default_ns(self) -> &'static str {
        self.get(slot::NS_DEFAULT).unwrap_or("latn")
    }
    /// The locale's second numbering system with its own symbols (native or default), "" for none.
    pub fn alt_ns(self) -> &'static str {
        self.s(slot::NS_ALT)
    }
    pub fn native_ns(self) -> &'static str {
        self.get(slot::NS_NATIVE).unwrap_or("latn")
    }
    pub fn min_grouping(self) -> u32 {
        self.get(slot::NS_MINGROUP).and_then(|s| s.parse().ok()).unwrap_or(1)
    }
    /// Symbol `i` (generator order: decimal, group, percentSign, plusSign, minusSign, approximatelySign,
    /// exponential, perMille, infinity, nan, timeSeparator, superscriptingExponent, list) for numbering system `ns`.
    pub fn symbol(self, ns: &str, i: usize) -> &'static str {
        if !ns.is_empty() && ns != "latn" && ns == self.alt_ns() {
            if let Some(v) = self.get(slot::SYM_ALT_DECIMAL + i) {
                return v;
            }
        }
        self.get(slot::SYM_LATN_DECIMAL + i).or_else(|| L::EN.get(slot::SYM_LATN_DECIMAL + i)).unwrap_or("")
    }
    /// Pattern `j` (decimal, percent, scientific, currency, currency-alpha, accounting, accounting-alpha).
    pub fn number_pattern(self, ns: &str, j: usize) -> &'static str {
        if !ns.is_empty() && ns != "latn" && ns == self.alt_ns() {
            if let Some(v) = self.get(slot::PAT_ALT_DECIMAL + j) {
                return v;
            }
        }
        self.get(slot::PAT_LATN_DECIMAL + j).or_else(|| L::EN.get(slot::PAT_LATN_DECIMAL + j)).unwrap_or("#,##0.###")
    }
    /// Compact pattern: style 0 short, 1 long, 2 currency short; `pow` 3..=14; plural category index.
    pub fn compact(self, style: usize, pow: u32, cat: usize) -> Option<&'static str> {
        if !(3..=14).contains(&pow) {
            return None;
        }
        let base = slot::COMPACT_0_3_ZERO + (style * 12 + (pow as usize - 3)) * 6;
        self.get(base + cat).or_else(|| self.get(base + 5))
    }
    pub fn currency(self, code: &str, field: usize) -> Option<&'static str> {
        self.keyed(CUR_KEYS, slot::CUR_BASE, slot::CUR_FIELDS, code, field)
    }
    /// Unit pattern: width 0 long, 1 short, 2 narrow; `f` 0..=5 plural category, 6 per-unit, 7 display name.
    pub fn unit(self, unit: &str, width: usize, f: usize) -> Option<&'static str> {
        self.keyed(UNIT_KEYS, slot::UNIT_BASE, slot::UNIT_FIELDS, unit, width * 8 + f)
    }

    // ---- dates
    /// Month name: ctx 0 format / 1 stand-alone; width 0 abbreviated, 1 narrow, 2 wide.
    pub fn month(self, ctx: usize, width: usize, m: usize) -> &'static str {
        self.s(slot::MONTH_FORMAT_ABBREVIATED_0 + ctx * 36 + width * 12 + m)
    }
    /// Day name: ctx 0 format / 1 stand-alone; width 0 abbreviated, 1 narrow, 2 short, 3 wide; Sunday = 0.
    pub fn day(self, ctx: usize, width: usize, d: usize) -> &'static str {
        self.s(slot::DAY_FORMAT_ABBREVIATED_0 + ctx * 28 + width * 7 + d)
    }
    /// Day period name: width 0 abbreviated, 1 narrow, 2 wide; id per `DP_IDS`.
    pub fn day_period(self, width: usize, id: &str) -> Option<&'static str> {
        let i = DP_IDS.iter().position(|x| *x == id)?;
        self.get(slot::DP_ABBREVIATED_AM + width * 12 + i)
    }
    /// Gregorian era name: width 0 wide, 1 abbreviated, 2 narrow; era 0 BC, 1 AD.
    pub fn era(self, width: usize, e: usize) -> &'static str {
        self.s(slot::ERA_WIDE_0 + width * 2 + e)
    }
    /// style 0 full, 1 long, 2 medium, 3 short.
    pub fn date_format(self, style: usize) -> &'static str {
        self.s(slot::DF_FULL + style)
    }
    pub fn time_format(self, style: usize) -> &'static str {
        self.s(slot::TF_FULL + style)
    }
    /// The date-time glue of a style; `at`: the "atTime" variant when the locale has one.
    pub fn date_time_format(self, style: usize, at: bool) -> &'static str {
        if at {
            if let Some(v) = self.get(slot::DTAT_FULL + style) {
                return v;
            }
        }
        self.get(slot::DTF_FULL + style).unwrap_or("{1}, {0}")
    }
    pub fn available_format(self, skeleton: &str) -> Option<&'static str> {
        self.keyed(AF_KEYS, slot::AF_BASE, 1, skeleton, 0)
    }
    pub fn interval_format(self, skeleton: &str, greatest: char) -> Option<&'static str> {
        let mut k = String::from(skeleton);
        k.push('/');
        k.push(greatest);
        self.keyed(IF_KEYS, slot::IF_BASE, 1, &k, 0)
    }
    /// Calendar `cal` (0 japanese, 1 buddhist, 2 roc) availableFormats where they differ from the Gregorian ones.
    pub fn calendar_format(self, cal: usize, skeleton: &str) -> Option<&'static str> {
        self.keyed(CALAF_KEYS, slot::CALAF_BASE, slot::CALAF_FIELDS, skeleton, cal)
    }
    /// Relative-time slot: field index per `FIELDS`, width 0 long / 1 short / 2 narrow, `x`: 0..=4 the relative
    /// phrases -2..=2, 5..=10 future by category, 11..=16 past by category, 17 the field's display name.
    pub fn relative(self, field: usize, width: usize, x: usize) -> Option<&'static str> {
        self.get(slot::REL_YEAR__2 + (field * 3 + width) * 18 + x)
    }
    /// List pattern: type per `LIST_TYPES`; part 0 start, 1 middle, 2 end, 3 pair.
    pub fn list(self, ty: usize, part: usize) -> &'static str {
        self.s(slot::LIST_STANDARD_START + ty * 4 + part)
    }

    // ---- names
    pub fn language_name(self, code: &str) -> Option<&'static str> {
        self.keyed(LANG_KEYS, slot::LANG_BASE, 1, code, 0)
    }
    pub fn region_name(self, code: &str) -> Option<&'static str> {
        self.keyed(REGION_KEYS, slot::REGION_BASE, 1, code, 0)
    }
    pub fn script_name(self, code: &str) -> Option<&'static str> {
        self.keyed(SCRIPT_KEYS, slot::SCRIPT_BASE, 1, code, 0)
    }
    pub fn calendar_name(self, code: &str) -> Option<&'static str> {
        self.keyed(CALNAME_KEYS, slot::CALNAME_BASE, 1, code, 0)
    }
    /// Metazone name: long 0 / short 1, kind 0 generic / 1 standard / 2 daylight.
    pub fn metazone_name(self, meta: usize, short: bool, kind: usize) -> Option<&'static str> {
        if meta >= META_KEYS.len() {
            return None;
        }
        self.get(slot::META_BASE + meta * 6 + if short { 3 } else { 0 } + kind)
    }
    /// A zone's own name (CLDR `zone` entries such as Europe/London's "British Summer Time").
    pub fn zone_name(self, zone: &str, short: bool, kind: usize) -> Option<&'static str> {
        self.keyed(ZONE_KEYS, slot::ZONE_BASE, 6, zone, if short { 3 } else { 0 } + kind)
    }
}

/// The relative-time fields in slot order.
pub const FIELDS: [&str; 8] = ["year", "quarter", "month", "week", "day", "hour", "minute", "second"];
/// The list pattern types in slot order.
pub const LIST_TYPES: [&str; 9] =
    ["standard", "standard-short", "standard-narrow", "or", "or-short", "or-narrow", "unit", "unit-short", "unit-narrow"];
/// The day period ids in slot order.
pub const DP_IDS: [&str; 12] =
    ["am", "pm", "midnight", "noon", "morning1", "morning2", "afternoon1", "afternoon2", "evening1", "evening2", "night1", "night2"];

/// The data locale of an available tag (case-insensitive), with the tag as the table spells it.
pub fn available(tag: &str) -> Option<(&'static str, L)> {
    AVAILABLE.iter().find(|(t, _)| t.eq_ignore_ascii_case(tag)).map(|(t, l)| (*t, L(*l)))
}

/// The data locale named exactly (a CLDR locale name).
pub fn locale(tag: &str) -> Option<L> {
    LOCS.iter().position(|l| l.tag.eq_ignore_ascii_case(tag)).map(|i| L(i as u8))
}

/// Every available tag (sorted).
pub fn available_tags() -> impl Iterator<Item = &'static str> {
    AVAILABLE.iter().map(|(t, _)| *t)
}

/// The ten digits of a numeric numbering system.
pub fn digits(ns: &str) -> Option<&'static str> {
    NUMSYS.binary_search_by(|(k, _)| k.cmp(&ns)).ok().map(|i| NUMSYS[i].1)
}

pub fn numbering_systems() -> impl Iterator<Item = &'static str> {
    NUMSYS.iter().map(|(k, _)| *k)
}

/// CLDR fraction digits of a currency (2 unless listed).
pub fn currency_digits(code: &str) -> u32 {
    CUR_DIGITS.iter().find(|(c, _)| *c == code).map(|(_, d)| *d as u32).unwrap_or(2)
}

pub fn currency_codes() -> impl Iterator<Item = &'static str> {
    CUR_KEYS.iter().copied()
}

pub fn unit_ids() -> impl Iterator<Item = &'static str> {
    UNIT_KEYS.iter().copied()
}

/// Likely subtags (UTS #35 §4.3) for one lookup key ("de", "und-TW", "zh-TW", "und-Hant").
pub fn likely(key: &str) -> Option<&'static str> {
    LIKELY.binary_search_by(|(k, _)| k.cmp(&key)).ok().map(|i| LIKELY[i].1)
}

/// timeData: the preferred hour symbol ("h", "H", ...) and the allowed list of a region.
pub fn hour_pref(region: &str) -> Option<(&'static str, &'static str)> {
    HOUR_PREF.binary_search_by(|(k, _, _)| k.cmp(&region)).ok().map(|i| (HOUR_PREF[i].1, HOUR_PREF[i].2))
}

/// The flexible day period (dayPeriodRuleSet) of `lang` at `hour`:`minute`; None when the language has no rules.
pub fn flexible_day_period(lang: &str, hour: u32, minute: u32) -> Option<&'static str> {
    let rules = DAY_PERIODS.iter().find(|(l, _)| *l == lang)?.1;
    if minute == 0 {
        for r in rules.split(',') {
            if let Some((id, h)) = r.split_once('@') {
                if h.parse::<u32>().ok() == Some(hour) {
                    return Some(id);
                }
            }
        }
    }
    for r in rules.split(',') {
        if let Some((id, span)) = r.split_once(':') {
            let (a, b) = span.split_once('-')?;
            let a: u32 = a.parse().ok()?;
            let b: u32 = b.parse().ok()?;
            let inside = if a < b { hour >= a && hour < b } else { hour >= a || hour < b };
            if inside {
                return Some(id);
            }
        }
    }
    None
}

/// The metazone (index into META_KEYS) a CLDR zone id uses now.
pub fn zone_meta(zone: &str) -> Option<usize> {
    ZONE_META.binary_search_by(|(k, _)| k.cmp(&zone)).ok().map(|i| ZONE_META[i].1 as usize)
}

/// The Japanese era index (0 Meiji .. 4 Reiwa) of a proleptic Gregorian date, None before Meiji.
pub fn japanese_era(y: i64, m: u32, d: u32) -> Option<(usize, i64)> {
    let mut found = None;
    for (i, (ey, em, ed)) in JA_ERAS.iter().enumerate() {
        let start = (*ey as i64, *em as u32, *ed as u32);
        if (y, m, d) >= start {
            found = Some((i, y - start.0 + 1));
        }
    }
    found
}

// ============================================================================================ plural rules

/// The operands of UTS #35 §5.1 (plural rules) of a formatted decimal: the integer digits, the visible fraction
/// digits, and the compact exponent.
#[derive(Clone, Debug, Default)]
pub struct Operands {
    pub int: String,
    pub frac: String,
    pub exp: u32,
}

impl Operands {
    pub fn new(int: &str, frac: &str, exp: u32) -> Operands {
        let i = int.trim_start_matches('0');
        Operands { int: String::from(if i.is_empty() { "0" } else { i }), frac: String::from(frac), exp }
    }
    fn digits_value(s: &str) -> Option<u64> {
        if s.len() > 18 {
            return None;
        }
        let mut v: u64 = 0;
        for b in s.bytes() {
            v = v * 10 + (b - b'0') as u64;
        }
        Some(v)
    }
    fn digits_mod(s: &str, m: u64) -> u64 {
        let mut v: u64 = 0;
        for b in s.bytes() {
            v = (v * 10 + (b - b'0') as u64) % m;
        }
        v
    }
    /// (value, is_integer) of operand `op` taken modulo `m` (0: no modulus); value None when it exceeds u64.
    fn value(&self, op: u8, m: u64) -> (Option<u64>, bool) {
        let trimmed = self.frac.trim_end_matches('0');
        let src: &str = match op {
            b'n' | b'i' => &self.int,
            b'f' => &self.frac,
            b't' => trimmed,
            b'v' => return (Some(self.frac.len() as u64 % if m == 0 { u64::MAX } else { m }), true),
            b'w' => return (Some(trimmed.len() as u64 % if m == 0 { u64::MAX } else { m }), true),
            _ => return (Some(self.exp as u64 % if m == 0 { u64::MAX } else { m }), true),
        };
        let integral = op != b'n' || trimmed.is_empty();
        let src = if src.is_empty() { "0" } else { src };
        if m != 0 {
            return (Some(Operands::digits_mod(src, m)), integral);
        }
        (Operands::digits_value(src), integral)
    }
}

fn relation_holds(rel: &str, o: &Operands) -> bool {
    let b = rel.as_bytes();
    if b.is_empty() {
        return true;
    }
    let op = b[0];
    let mut i = 1;
    let mut m: u64 = 0;
    if i < b.len() && b[i] == b'%' {
        i += 1;
        while i < b.len() && b[i].is_ascii_digit() {
            m = m * 10 + (b[i] - b'0') as u64;
            i += 1;
        }
    }
    let negate = b.get(i) == Some(&b'!');
    i += 1;
    let (v, integral) = o.value(op, m);
    let mut hit = false;
    if integral {
        if let Some(v) = v {
            for range in rel[i..].split(',') {
                let (a, c) = range.split_once("..").unwrap_or((range, range));
                let a: u64 = a.parse().unwrap_or(0);
                let c: u64 = c.parse().unwrap_or(0);
                if v >= a && v <= c {
                    hit = true;
                    break;
                }
            }
        }
    }
    hit != negate
}

fn condition_holds(cond: &str, o: &Operands) -> bool {
    cond.split('|').any(|and| and.split('&').all(|r| relation_holds(r, o)))
}

fn plural_row(lang: &str) -> Option<&'static (&'static str, &'static str, &'static str, &'static str)> {
    PLURALS.iter().find(|r| r.0 == lang)
}

/// The plural category (ECMA-402 §16.5.3 ResolvePlural / PluralRuleSelect) of `o` in `lang`.
pub fn plural(lang: &str, ordinal: bool, o: &Operands) -> &'static str {
    let Some(row) = plural_row(lang).or_else(|| plural_row("en")) else { return "other" };
    let rules = if ordinal { row.2 } else { row.1 };
    for r in rules.split(';') {
        if let Some((cat, cond)) = r.split_once(':') {
            if condition_holds(cond, o) {
                return CATS[cat_index(cat)];
            }
        }
    }
    "other"
}

/// The categories `lang` uses, in CLDR order, "other" last.
pub fn plural_categories(lang: &str, ordinal: bool) -> Vec<&'static str> {
    let mut out = Vec::new();
    if let Some(row) = plural_row(lang).or_else(|| plural_row("en")) {
        let rules = if ordinal { row.2 } else { row.1 };
        for c in CATS.iter().take(5) {
            if rules.split(';').any(|r| r.split_once(':').map(|(k, _)| k == *c).unwrap_or(false)) {
                out.push(*c);
            }
        }
    }
    out.push("other");
    out
}

/// CLDR plural ranges: the category of a range from `a` to `b`.
pub fn plural_range(lang: &str, a: &str, b: &str) -> &'static str {
    if let Some(row) = plural_row(lang) {
        for r in row.3.split(';') {
            if let Some((k, v)) = r.split_once(':') {
                if let Some((x, y)) = k.split_once('-') {
                    if x == a && y == b {
                        return CATS[cat_index(v)];
                    }
                }
            }
        }
    }
    CATS[cat_index(b)]
}
